import {
  AlertTriangle,
  CheckCircle2,
  Loader2,
  MessageSquare,
  PenLine,
  Save,
  X,
  XCircle,
} from 'lucide-react'
import { useEffect, useState } from 'react'

import { useAuth } from '@/src/contexts/AuthContext'
import {
  AttemptDetailAnswer,
  quizAnalyticsService,
} from '@/src/features/quizzes/api/quizAnalyticsService'
import { gradeAttemptQuestion } from '@/src/features/quizzes/api/quizManager.service'
import { cn } from '@/src/utils/cn'

interface AttemptDetailModalProps {
  attemptId: string
  studentName: string
  score: number | null
  passed: boolean | null
  onClose: () => void
  onGraded?: () => void
}

/** Returns true if a question type requires manual grading */
function isEssayType(type: AttemptDetailAnswer['question_type']): boolean {
  return type === 'ESSAY' || type === 'SHORT_ANSWER'
}

/** Determines if an essay/short-answer question still needs grading */
function needsGrading(answer: AttemptDetailAnswer): boolean {
  return isEssayType(answer.question_type) && answer.is_correct === null
}

export function AttemptDetailModal({
  attemptId,
  studentName,
  score,
  passed,
  onClose,
  onGraded,
}: AttemptDetailModalProps) {
  const { tenantId } = useAuth()
  const [answers, setAnswers] = useState<AttemptDetailAnswer[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Grading state keyed by question_id
  const [gradingScores, setGradingScores] = useState<Record<string, string>>({})
  const [gradingComments, setGradingComments] = useState<Record<string, string>>({})
  const [gradingSaving, setGradingSaving] = useState<Record<string, boolean>>({})
  const [gradingToast, setGradingToast] = useState<
    Record<string, { type: 'success' | 'error'; message: string }>
  >({})

  useEffect(() => {
    async function loadDetail() {
      setIsLoading(true)
      setError(null)
      try {
        const data = await quizAnalyticsService.getAttemptDetail(attemptId)
        setAnswers(data)

        // Pre-fill grading inputs for already-graded essay questions
        const scores: Record<string, string> = {}
        const comments: Record<string, string> = {}
        for (const a of data) {
          if (isEssayType(a.question_type)) {
            scores[a.question_id] = a.points_earned != null ? String(a.points_earned) : ''
            comments[a.question_id] = a.grader_comment ?? ''
          }
        }
        setGradingScores(scores)
        setGradingComments(comments)
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : 'Gagal memuat detail jawaban')
      } finally {
        setIsLoading(false)
      }
    }
    loadDetail()
  }, [attemptId])

  const correctCount = answers.filter((a) => a.is_correct).length
  const ungradedCount = answers.filter(needsGrading).length

  const handleGrade = async (answer: AttemptDetailAnswer) => {
    const scoreStr = gradingScores[answer.question_id] ?? ''
    const scoreVal = parseFloat(scoreStr)

    if (isNaN(scoreVal) || scoreVal < 0 || scoreVal > answer.max_points) {
      setGradingToast((prev) => ({
        ...prev,
        [answer.question_id]: {
          type: 'error',
          message: `Nilai harus antara 0 dan ${answer.max_points}`,
        },
      }))
      return
    }

    setGradingSaving((prev) => ({ ...prev, [answer.question_id]: true }))
    setGradingToast((prev) => {
      const next = { ...prev }
      delete next[answer.question_id]
      return next
    })

    try {
      const isCorrect = scoreVal >= answer.max_points * 0.7
      const comment = gradingComments[answer.question_id] || undefined

      await gradeAttemptQuestion(
        attemptId,
        answer.question_id,
        tenantId!,
        scoreVal,
        isCorrect,
        comment
      )

      // Update local state to reflect the grading
      setAnswers((prev) =>
        prev.map((a) =>
          a.question_id === answer.question_id
            ? {
                ...a,
                points_earned: scoreVal,
                is_correct: isCorrect,
                grader_comment: comment ?? null,
                graded_at: new Date().toISOString(),
              }
            : a
        )
      )

      setGradingToast((prev) => ({
        ...prev,
        [answer.question_id]: {
          type: 'success',
          message: 'Nilai berhasil disimpan',
        },
      }))

      onGraded?.()

      // Auto-dismiss success toast
      setTimeout(() => {
        setGradingToast((prev) => {
          const next = { ...prev }
          if (next[answer.question_id]?.type === 'success') {
            delete next[answer.question_id]
          }
          return next
        })
      }, 3000)
    } catch (err: unknown) {
      setGradingToast((prev) => ({
        ...prev,
        [answer.question_id]: {
          type: 'error',
          message: err instanceof Error ? err.message : 'Gagal menyimpan nilai',
        },
      }))
    } finally {
      setGradingSaving((prev) => ({ ...prev, [answer.question_id]: false }))
    }
  }

  /** Determine the border color for a question card */
  function getCardStyle(answer: AttemptDetailAnswer) {
    if (isEssayType(answer.question_type)) {
      if (answer.is_correct === null) {
        // Ungraded essay
        return 'bg-amber-50/50 border-amber-300'
      }
      return answer.is_correct
        ? 'bg-emerald-50/50 border-emerald-200'
        : 'bg-red-50/50 border-red-200'
    }
    return answer.is_correct ? 'bg-emerald-50/50 border-emerald-200' : 'bg-red-50/50 border-red-200'
  }

  /** Determine the status icon for a question */
  function getStatusIcon(answer: AttemptDetailAnswer) {
    if (isEssayType(answer.question_type) && answer.is_correct === null) {
      return <PenLine className="w-5 h-5 text-amber-500" />
    }
    return answer.is_correct ? (
      <CheckCircle2 className="w-5 h-5 text-emerald-500" />
    ) : (
      <XCircle className="w-5 h-5 text-red-500" />
    )
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />

      {/* Modal */}
      <div className="relative w-full max-w-2xl max-h-[85vh] bg-white rounded-2xl shadow-2xl flex flex-col mx-4 animate-in fade-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-slate-100">
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-lg font-bold text-slate-900">Detail Jawaban</h2>
              {ungradedCount > 0 && (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-700">
                  <PenLine className="w-3 h-3" />
                  {ungradedCount} Perlu Dinilai
                </span>
              )}
            </div>
            <div className="flex items-center gap-3 mt-1">
              <span className="text-sm text-slate-500">{studentName}</span>
              <span className="text-xs text-slate-300">&#8226;</span>
              <span
                className={cn(
                  'text-sm font-bold',
                  passed ? 'text-emerald-600' : passed === false ? 'text-red-600' : 'text-slate-400'
                )}
              >
                Skor: {score ?? '-'}
              </span>
              {passed !== null && (
                <span
                  className={cn(
                    'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-bold',
                    passed ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                  )}
                >
                  {passed ? <CheckCircle2 className="w-3 h-3" /> : <XCircle className="w-3 h-3" />}
                  {passed ? 'Lulus' : 'Tidak Lulus'}
                </span>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-slate-100 rounded-xl transition-colors text-slate-400 hover:text-slate-600"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          {isLoading ? (
            <div className="flex items-center justify-center py-12 text-slate-400 gap-2">
              <Loader2 className="w-5 h-5 animate-spin" />
              <span className="text-sm">Memuat jawaban...</span>
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-12 text-red-500 gap-2">
              <AlertTriangle className="w-8 h-8 opacity-50" />
              <p className="text-sm">{error}</p>
            </div>
          ) : answers.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-slate-400">
              <p className="text-sm">Tidak ada data jawaban untuk percobaan ini.</p>
            </div>
          ) : (
            answers.map((answer, idx) => (
              <div
                key={answer.question_id}
                className={cn('p-4 rounded-xl border transition-colors', getCardStyle(answer))}
              >
                <div className="flex items-start justify-between gap-2 mb-3">
                  <div className="flex items-start gap-2 flex-1 min-w-0">
                    <p className="text-sm font-semibold text-slate-800">
                      <span className="text-slate-400 mr-1">{idx + 1}.</span>
                      {answer.question_text}
                    </p>
                    {needsGrading(answer) && (
                      <span className="shrink-0 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-700 whitespace-nowrap">
                        Perlu Dinilai
                      </span>
                    )}
                  </div>
                  <span className="shrink-0">{getStatusIcon(answer)}</span>
                </div>

                <div className="space-y-1.5 text-sm">
                  {/* Student's answer */}
                  <div
                    className={cn(
                      'flex items-start gap-2 px-3 py-2 rounded-lg',
                      isEssayType(answer.question_type) && answer.is_correct === null
                        ? 'bg-amber-100/70 text-amber-800'
                        : answer.is_correct
                          ? 'bg-emerald-100/70 text-emerald-800'
                          : 'bg-red-100/70 text-red-800'
                    )}
                  >
                    <span className="font-medium text-xs uppercase tracking-wide opacity-60 shrink-0 pt-0.5">
                      Jawaban Siswa:
                    </span>
                    <span className="font-semibold whitespace-pre-wrap">
                      {answer.selected_option_text || answer.text_answer || 'Tidak menjawab'}
                    </span>
                  </div>

                  {/* Correct answer (only show if student got it wrong and it's an MCQ-like question) */}
                  {!answer.is_correct &&
                    answer.correct_option_text &&
                    !isEssayType(answer.question_type) && (
                      <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-emerald-100/40 text-emerald-700">
                        <span className="font-medium text-xs uppercase tracking-wide opacity-60">
                          Jawaban Benar:
                        </span>
                        <span className="font-semibold">{answer.correct_option_text}</span>
                      </div>
                    )}

                  {/* Show grading result for already-graded essay questions */}
                  {isEssayType(answer.question_type) && answer.is_correct !== null && (
                    <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-slate-100/70 text-slate-700">
                      <span className="font-medium text-xs uppercase tracking-wide opacity-60">
                        Nilai:
                      </span>
                      <span className="font-bold">
                        {answer.points_earned ?? 0} / {answer.max_points}
                      </span>
                    </div>
                  )}

                  {/* Show existing grader comment if present */}
                  {answer.grader_comment && !isEssayType(answer.question_type) && (
                    <div className="mt-2 p-3 bg-purple-50/50 border border-purple-100 rounded-lg">
                      <span className="font-bold text-xs uppercase tracking-wide text-purple-800 mb-1 block">
                        Komentar Penilai:
                      </span>
                      <p className="text-sm text-purple-900/80 leading-relaxed">
                        {answer.grader_comment}
                      </p>
                    </div>
                  )}

                  {/* Explanation */}
                  {answer.explanation && (
                    <div className="mt-3 p-3 bg-blue-50/50 border border-blue-100 rounded-lg">
                      <span className="font-bold text-xs uppercase tracking-wide text-blue-800 mb-1 block">
                        Penjelasan:
                      </span>
                      <p className="text-sm text-blue-900/80 leading-relaxed">
                        {answer.explanation}
                      </p>
                    </div>
                  )}

                  {/* Essay / Short Answer Grading Form */}
                  {isEssayType(answer.question_type) && (
                    <div className="mt-3 p-4 bg-white border border-slate-200 rounded-xl space-y-3">
                      <div className="flex items-center gap-2 text-sm font-bold text-slate-700">
                        <PenLine className="w-4 h-4 text-slate-500" />
                        Penilaian Manual
                      </div>

                      {/* Score input */}
                      <div className="flex items-center gap-3">
                        <label className="text-xs font-medium text-slate-500 uppercase tracking-wide shrink-0">
                          Nilai
                        </label>
                        <div className="flex items-center gap-2">
                          <input
                            type="number"
                            min={0}
                            max={answer.max_points}
                            step="0.5"
                            value={gradingScores[answer.question_id] ?? ''}
                            onChange={(e) =>
                              setGradingScores((prev) => ({
                                ...prev,
                                [answer.question_id]: e.target.value,
                              }))
                            }
                            placeholder="0"
                            className="w-20 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm text-center focus:ring-2 focus:ring-blue-500 outline-none"
                          />
                          <span className="text-sm text-slate-400">/ {answer.max_points}</span>
                        </div>
                      </div>

                      {/* Feedback textarea */}
                      <div>
                        <label className="flex items-center gap-1.5 text-xs font-medium text-slate-500 uppercase tracking-wide mb-1.5">
                          <MessageSquare className="w-3 h-3" />
                          Komentar
                        </label>
                        <textarea
                          value={gradingComments[answer.question_id] ?? ''}
                          onChange={(e) =>
                            setGradingComments((prev) => ({
                              ...prev,
                              [answer.question_id]: e.target.value,
                            }))
                          }
                          placeholder="Berikan komentar untuk siswa (opsional)..."
                          rows={2}
                          className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                        />
                      </div>

                      {/* Toast message */}
                      {gradingToast[answer.question_id] && (
                        <div
                          className={cn(
                            'px-3 py-2 rounded-lg text-xs font-medium',
                            gradingToast[answer.question_id].type === 'success'
                              ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                              : 'bg-red-50 text-red-700 border border-red-200'
                          )}
                        >
                          {gradingToast[answer.question_id].message}
                        </div>
                      )}

                      {/* Save button */}
                      <button
                        onClick={() => handleGrade(answer)}
                        disabled={gradingSaving[answer.question_id]}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {gradingSaving[answer.question_id] ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <Save className="w-4 h-4" />
                        )}
                        Simpan Nilai
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer */}
        {!isLoading && !error && answers.length > 0 && (
          <div className="p-4 border-t border-slate-100 flex items-center justify-between">
            <span className="text-sm text-slate-500">
              {correctCount} dari {answers.length} soal benar
              {ungradedCount > 0 && (
                <span className="text-amber-600 ml-2">({ungradedCount} belum dinilai)</span>
              )}
            </span>
            <div className="w-32 h-2 bg-slate-200 rounded-full overflow-hidden">
              <div
                className={cn(
                  'h-full rounded-full transition-all',
                  correctCount / answers.length >= 0.7
                    ? 'bg-emerald-500'
                    : correctCount / answers.length >= 0.4
                      ? 'bg-amber-500'
                      : 'bg-red-500'
                )}
                style={{ width: `${(correctCount / answers.length) * 100}%` }}
              />
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

import {
  DragDropContext,
  Draggable,
  type DragStart,
  Droppable,
  type DropResult,
} from '@hello-pangea/dnd'
import {
  ArrowDown,
  ArrowUp,
  File,
  FileText,
  GripVertical,
  HelpCircle,
  Image,
  Loader2,
  Package,
  Plus,
  Trash2,
  Type,
  Video,
  X,
} from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { useState } from 'react'

import { useBuilder } from '@/src/contexts/BuilderContext'
import { QuizBlockEditor } from '@/src/features/quizzes/components/QuizBlockEditor'
import { cn } from '@/src/utils/cn'

import { AssignmentBlockEditor } from './blocks/AssignmentBlockEditor'
import { FileBlockEditor } from './blocks/FileBlockEditor'
import { ImageBlockEditor } from './blocks/ImageBlockEditor'
import { ScormBlockEditor } from './blocks/ScormBlockEditor'
import { TextBlockEditor } from './blocks/TextBlockEditor'
import { VideoBlockEditor } from './blocks/VideoBlockEditor'
import { CollaboratorCursor } from './CollaboratorCursor'

export function LessonBlockEditor() {
  const { state, actions, presence, mobile } = useBuilder()
  const [showAddMenu, setShowAddMenu] = useState(false)

  if (!state.activeLesson) {
    return (
      <main
        id="builder-main"
        aria-label="Editor konten"
        className="flex-1 flex items-center justify-center bg-slate-50/50 dark:bg-slate-900/50 p-6"
      >
        <div className="text-center max-w-sm p-12 bg-white dark:bg-slate-800 rounded-[32px] shadow-xl shadow-slate-200/50 dark:shadow-slate-900/50 border border-slate-100/80 dark:border-slate-700/80">
          <div className="w-24 h-24 bg-indigo-50 dark:bg-indigo-950 text-indigo-600 dark:text-indigo-400 rounded-[32px] flex items-center justify-center mx-auto mb-8 shadow-inner">
            <FileText className="w-12 h-12" />
          </div>
          <h3 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-4 tracking-tight">
            Mulai Menyusun
          </h3>
          <p className="text-sm font-medium text-slate-500 dark:text-slate-400 leading-relaxed max-w-[280px] mx-auto">
            Pilih satu materi dari daftar kurikulum untuk mulai mengisi konten pembelajaran.
          </p>
        </div>
      </main>
    )
  }

  if (state.loadingBlocks) {
    return (
      <main
        id="builder-main"
        aria-label="Editor konten"
        className="flex-1 flex items-center justify-center bg-transparent"
      >
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          <p className="text-sm font-medium text-slate-500 dark:text-slate-400 animate-pulse">
            Memuat data pelajaran...
          </p>
        </div>
      </main>
    )
  }

  const activeLesson = state.modules
    .flatMap((m) => m.lessons)
    .find((l) => l.id === state.activeLesson?.id)

  const getBlockIcon = (type: string) => {
    switch (type?.toUpperCase()) {
      case 'TEXT':
        return <Type className="w-4 h-4 text-slate-500" />
      case 'VIDEO':
        return <Video className="w-4 h-4 text-blue-500" />
      case 'IMAGE':
        return <Image className="w-4 h-4 text-emerald-500" />
      case 'FILE':
        return <File className="w-4 h-4 text-orange-500" />
      case 'QUIZ':
        return <HelpCircle className="w-4 h-4 text-rose-500" />
      case 'ASSIGNMENT':
        return <FileText className="w-4 h-4 text-indigo-500" />
      case 'SCORM':
        return <Package className="w-4 h-4 text-teal-500" />
      default:
        return <FileText className="w-4 h-4 text-slate-500" />
    }
  }

  const handleDragStart = (_start: DragStart) => {
    if (mobile.isMobile || mobile.isTablet) {
      try {
        navigator.vibrate?.(50)
      } catch {
        /* ignore */
      }
    }
  }

  const handleDragEnd = (result: DropResult) => {
    if (!result.destination) return
    const blockIds = state.activeLesson!.blocks.map((b) => b.id)
    const [moved] = blockIds.splice(result.source.index, 1)
    blockIds.splice(result.destination.index, 0, moved)
    actions.reorderBlocks(blockIds)
  }

  const handleMoveUp = (index: number) => {
    if (index === 0) return
    const blockIds = state.activeLesson!.blocks.map((b) => b.id)
    const temp = blockIds[index]
    blockIds[index] = blockIds[index - 1]
    blockIds[index - 1] = temp
    actions.reorderBlocks(blockIds)
  }

  const handleMoveDown = (index: number) => {
    const blocks = state.activeLesson!.blocks
    if (index === blocks.length - 1) return
    const blockIds = blocks.map((b) => b.id)
    const temp = blockIds[index]
    blockIds[index] = blockIds[index + 1]
    blockIds[index + 1] = temp
    actions.reorderBlocks(blockIds)
  }

  const handleAddBlock = (type: string) => {
    actions.addBlock(type)
    setShowAddMenu(false)
  }

  const blockTypes = [
    {
      type: 'text',
      label: 'Teks',
      icon: <Type className="w-5 h-5" />,
      color: 'text-slate-700 bg-white hover:bg-slate-50 border-slate-200',
    },
    {
      type: 'video',
      label: 'Video',
      icon: <Video className="w-5 h-5" />,
      color: 'text-blue-600 bg-blue-50/30 hover:bg-blue-50 border-blue-100',
    },
    {
      type: 'image',
      label: 'Gambar',
      icon: <Image className="w-5 h-5" />,
      color: 'text-emerald-600 bg-emerald-50/30 hover:bg-emerald-50 border-emerald-100',
    },
    {
      type: 'file',
      label: 'File',
      icon: <File className="w-5 h-5" />,
      color: 'text-orange-600 bg-orange-50/30 hover:bg-orange-50 border-orange-100',
    },
    {
      type: 'quiz',
      label: 'Kuis',
      icon: <HelpCircle className="w-5 h-5" />,
      color: 'text-rose-600 bg-rose-50/30 hover:bg-rose-50 border-rose-100',
    },
    {
      type: 'assignment',
      label: 'Tugas',
      icon: <FileText className="w-5 h-5" />,
      color: 'text-indigo-600 bg-indigo-50/30 hover:bg-indigo-50 border-indigo-100',
    },
    {
      type: 'scorm',
      label: 'SCORM',
      icon: <Package className="w-5 h-5" />,
      color: 'text-teal-600 bg-teal-50/30 hover:bg-teal-50 border-teal-100',
    },
  ]

  return (
    <main
      id="builder-main"
      aria-label="Editor konten"
      className="flex-1 overflow-y-auto bg-slate-50 dark:bg-slate-900"
    >
      <div className={cn('max-w-3xl mx-auto py-8', mobile.isMobile ? 'px-4' : 'px-6')}>
        {/* Lesson Header */}
        <div className="mb-10 p-6 md:p-8 bg-white dark:bg-slate-800 rounded-[32px] border border-slate-200/60 dark:border-slate-700/60 shadow-sm">
          <input
            type="text"
            value={activeLesson?.title || ''}
            onChange={(e) => {
              if (activeLesson) {
                actions.updateLesson(activeLesson.id, { title: e.target.value })
              }
            }}
            className={cn(
              'w-full font-black text-slate-800 dark:text-slate-100 bg-transparent border-none outline-none placeholder:text-slate-400 focus:ring-0 tracking-tight',
              mobile.isMobile ? 'text-2xl' : 'text-3xl'
            )}
            placeholder="Judul Materi..."
            aria-label="Judul materi"
          />
          <div className="flex items-center gap-3 mt-4">
            <span
              className={cn(
                'text-[10px] font-black uppercase tracking-[0.15em] px-3 py-1 rounded-full shadow-sm',
                activeLesson?.isPublished
                  ? 'bg-emerald-500 text-white shadow-emerald-50'
                  : 'bg-amber-400 text-amber-900 shadow-amber-50'
              )}
            >
              {activeLesson?.isPublished ? 'Dipublikasi' : 'Draf'}
            </span>
            <div className="h-4 w-[1px] bg-slate-200 mx-1" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
              {state.activeLesson.blocks.length} KONTEN
            </span>
          </div>
        </div>

        {/* Block List with DND */}
        <DragDropContext onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
          <Droppable droppableId="blocks" type="BLOCK">
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                className="space-y-4 md:space-y-3"
              >
                <AnimatePresence>
                  {state.activeLesson!.blocks.map((block, idx) => {
                    const locker = presence.getBlockLocker(block.id)
                    const isLocked = !!locker

                    return (
                      <Draggable
                        key={block.id}
                        draggableId={block.id}
                        index={idx}
                        isDragDisabled={isLocked}
                      >
                        {(dragProvided, snapshot) => (
                          <motion.div
                            ref={dragProvided.innerRef}
                            {...dragProvided.draggableProps}
                            initial={{ opacity: 0, y: 15 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            onClick={() => {
                              if (!isLocked) presence.updateActiveBlock(block.id)
                            }}
                            className={cn(
                              'bg-white dark:bg-slate-800 rounded-[24px] border shadow-sm group transition-all relative overflow-hidden',
                              snapshot.isDragging
                                ? 'shadow-2xl ring-2 ring-indigo-500/20 border-indigo-400 z-50 scale-[1.02]'
                                : 'border-slate-200/70 dark:border-slate-700/70 hover:shadow-md hover:border-slate-300 dark:hover:border-slate-600',
                              isLocked && 'pointer-events-none opacity-90 grayscale-[0.3]'
                            )}
                          >
                            {/* Collaborator overlay if locked */}
                            {locker && <CollaboratorCursor locker={locker} />}

                            {/* Block Header */}
                            <div className="flex items-center gap-2 md:gap-3 px-3 md:px-5 py-3 md:py-4 border-b border-slate-50 dark:border-slate-700/50">
                              <div
                                {...dragProvided.dragHandleProps}
                                className="p-2 flex items-center justify-center min-w-[44px] min-h-[44px] text-slate-400 dark:text-slate-600 hover:text-slate-600 dark:hover:text-slate-400 cursor-grab hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg transition-colors touch-none"
                                aria-label="Pindah konten"
                              >
                                <GripVertical className="w-5 h-5" />
                              </div>
                              <div className="p-2 bg-slate-50 dark:bg-slate-700 rounded-lg">
                                {getBlockIcon(block.type)}
                              </div>
                              <span className="text-xs font-black text-slate-500 uppercase tracking-[0.2em] flex-1">
                                {{
                                  text: 'TEKS',
                                  video: 'VIDEO',
                                  image: 'GAMBAR',
                                  file: 'FILE',
                                  quiz: 'KUIS',
                                  assignment: 'TUGAS',
                                  scorm: 'SCORM',
                                }[block.type.toLowerCase()] || block.type.toUpperCase()}
                              </span>

                              {/* Non-drag alternative buttons */}
                              <div className="flex items-center md:opacity-0 md:group-hover:opacity-100 transition-opacity gap-1 mr-2">
                                <button
                                  onClick={() => handleMoveUp(idx)}
                                  disabled={idx === 0}
                                  className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-500 rounded-xl transition-all disabled:opacity-30"
                                  aria-label="Pindah ke atas"
                                  title="Pindah ke atas"
                                >
                                  <ArrowUp className="w-4 h-4" />
                                </button>
                                <button
                                  onClick={() => handleMoveDown(idx)}
                                  disabled={idx === state.activeLesson!.blocks.length - 1}
                                  className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-500 rounded-xl transition-all disabled:opacity-30"
                                  aria-label="Pindah ke bawah"
                                  title="Pindah ke bawah"
                                >
                                  <ArrowDown className="w-4 h-4" />
                                </button>
                              </div>

                              <button
                                onClick={() => {
                                  if (confirm('Hapus konten ini?')) {
                                    actions.deleteBlock(block.id)
                                  }
                                }}
                                className="p-2 md:opacity-0 md:group-hover:opacity-100 hover:bg-rose-50 text-slate-500 hover:text-rose-600 rounded-xl transition-all"
                                aria-label="Hapus konten"
                                title="Hapus konten"
                              >
                                <Trash2 className="w-5 h-5" />
                              </button>
                            </div>

                            {/* Block Content */}
                            <div className={cn('py-4 md:py-5', mobile.isMobile ? 'px-4' : 'px-6')}>
                              {renderBlockContent(block)}
                            </div>
                          </motion.div>
                        )}
                      </Draggable>
                    )
                  })}
                </AnimatePresence>
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>

        {/* Add Block Button */}
        <div className="relative mt-8">
          <button
            onClick={() => setShowAddMenu(!showAddMenu)}
            aria-expanded={showAddMenu}
            className={cn(
              'w-full py-5 rounded-[24px] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-2 transition-all',
              'border-2 border-dashed outline-none focus-visible:ring-2 focus-visible:ring-indigo-500',
              showAddMenu
                ? 'border-indigo-300 dark:border-indigo-700 bg-indigo-50 dark:bg-indigo-950/50 text-indigo-600 dark:text-indigo-400 shadow-inner'
                : 'border-slate-200 dark:border-slate-700 text-slate-500 hover:text-indigo-600 hover:border-indigo-300 hover:bg-white dark:hover:bg-slate-800 hover:shadow-md'
            )}
          >
            {showAddMenu ? <X className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
            {showAddMenu ? 'BATALKAN' : 'TAMBAH KONTEN'}
          </button>

          {/* Block Type Menu */}
          <AnimatePresence>
            {showAddMenu && (
              <motion.div
                initial={{ opacity: 0, y: 15, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className={cn('mt-4 grid gap-3', mobile.isMobile ? 'grid-cols-2' : 'grid-cols-3')}
              >
                {blockTypes.map((bt) => (
                  <button
                    key={bt.type}
                    onClick={() => handleAddBlock(bt.type)}
                    className={cn(
                      'py-5 rounded-[24px] font-black text-xs uppercase tracking-[0.1em] flex flex-col items-center gap-3 transition-all border shadow-sm hover:shadow-md hover:-translate-y-1 outline-none focus-visible:ring-2 focus-visible:ring-indigo-500',
                      bt.color
                    )}
                  >
                    <div className="p-3 bg-white rounded-xl shadow-sm">{bt.icon}</div>
                    {bt.label}
                  </button>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </main>
  )
}

function renderBlockContent(block: {
  id: string
  type: string
  content: string | null
  url: string | null
}) {
  switch (block.type?.toUpperCase()) {
    case 'TEXT':
      return <TextBlockEditor blockId={block.id} />
    case 'VIDEO':
      return <VideoBlockEditor blockId={block.id} />
    case 'IMAGE':
      return <ImageBlockEditor blockId={block.id} />
    case 'FILE':
      return <FileBlockEditor blockId={block.id} />
    case 'QUIZ':
      return <QuizBlockEditor blockId={block.id} />
    case 'ASSIGNMENT':
      return <AssignmentBlockEditor blockId={block.id} />
    case 'SCORM':
      return <ScormBlockEditor blockId={block.id} />
    default:
      return <p className="text-xs text-slate-500">Unknown block type: {block.type}</p>
  }
}

import { api } from "@/src/lib/api"
import { useCallback, useEffect, useRef } from 'react'

import { lessonService } from '@/src/features/lessons'

interface ProgressReporterProps {
  lessonId: string
  tenantId: string
  status: 'started' | 'in_progress' | 'completed'
  progressPercentage: number
  lastPosition?: number
  enabled: boolean
}

/**
 * ProgressReporter — Invisible component that throttles progress updates to API.
 * Sends updates every 5 seconds using the monotonic RPC function.
 */
export function ProgressReporter({
  lessonId,
  tenantId,
  status,
  progressPercentage,
  lastPosition,
  enabled,
}: ProgressReporterProps) {
  const lastSent = useRef({ percentage: 0, position: 0 })
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const sendUpdate = useCallback(async () => {
    // Only send if there's meaningful change
    if (
      progressPercentage <= lastSent.current.percentage &&
      (lastPosition ?? 0) <= lastSent.current.position
    ) {
      return
    }

    try {
      await lessonService.queueProgressUpdate(
        lessonId,
        tenantId,
        status,
        progressPercentage,
        lastPosition
      )
      lastSent.current = {
        percentage: progressPercentage,
        position: lastPosition ?? 0,
      }
    } catch (err) {
      if (import.meta.env.DEV) console.error('[ProgressReporter] Failed to sync:', err)
    }
  }, [lessonId, tenantId, status, progressPercentage, lastPosition])

  // Throttled 5-second interval
  useEffect(() => {
    if (!enabled) return

    intervalRef.current = setInterval(sendUpdate, 5000)

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current)
    }
  }, [enabled, sendUpdate])

  // Handle online and beforeunload events
  useEffect(() => {
    const handleOnline = () => {
      lessonService.processOfflineQueue(tenantId)
    }

    const handleBeforeUnload = () => {
      // Flush immediate progress to queue if it hasn't been sent yet
      if (
        progressPercentage > lastSent.current.percentage ||
        (lastPosition ?? 0) > lastSent.current.position
      ) {
        lessonService.queueProgressUpdate(
          lessonId,
          tenantId,
          status,
          progressPercentage,
          lastPosition
        )
      }
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('beforeunload', handleBeforeUnload)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('beforeunload', handleBeforeUnload)
    }
  }, [tenantId, lessonId, status, progressPercentage, lastPosition])

  // Flush on unmount or lesson change
  useEffect(() => {
    return () => {
      if (progressPercentage > lastSent.current.percentage) {
        sendUpdate()
      }
    }
  }, [lessonId]) // eslint-disable-line react-hooks/exhaustive-deps

  // This is an invisible reporting component
  return null
}

import { api } from "@/src/lib/api"
import { formatDistanceToNow } from 'date-fns'
import { id as localeId } from 'date-fns/locale'
import { Edit2, MessageSquare, MoreVertical, Pin, Send, Trash2 } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { memo, useCallback, useEffect, useState } from 'react'

import { OptimizedImage } from '@/src/components/ui'
import { useAuth } from '@/src/contexts/AuthContext'
import { Discussion, discussionService } from '@/src/features/discussions/api/discussionService'
import { useToast } from '@/src/hooks/useToast'
import { cn } from '@/src/utils/cn'

// ⚡ Perf: CommentItem extracted to file-level and wrapped in React.memo.
// Previously defined INSIDE CommentSection's render body, which caused React
// to treat it as a brand-new component type on every parent render — unmounting
// and remounting all comment DOM (losing focus, scroll position, animations).
interface CommentItemProps {
  comment: Discussion
  isReply?: boolean
  userId?: string
  userRole?: string | null
  editingComment: string | null
  editContent: string
  openMenuId: string | null
  replyingTo: string | null
  newComment: string
  onSetEditingComment: (id: string | null) => void
  onSetEditContent: (content: string) => void
  onSetOpenMenuId: (id: string | null) => void
  onSetReplyingTo: (id: string | null) => void
  onSetNewComment: (content: string) => void
  onSubmit: (e?: React.FormEvent, parentId?: string | null) => void
  onDelete: (id: string) => void
  onTogglePin: (id: string, currentPin: boolean) => void
}

const CommentItem = memo(function CommentItem({
  comment,
  isReply = false,
  userId,
  userRole,
  editingComment,
  editContent,
  openMenuId,
  replyingTo,
  newComment,
  onSetEditingComment,
  onSetEditContent,
  onSetOpenMenuId,
  onSetReplyingTo,
  onSetNewComment,
  onSubmit,
  onDelete,
  onTogglePin,
}: CommentItemProps) {
  const isAuthor = comment.author_id === userId
  const isAdmin = userRole === 'admin' || userRole === 'teacher'
  const canManage = isAuthor || isAdmin

  return (
    <div className={cn('flex gap-3', isReply && 'ml-11 mt-4')}>
      <div className="w-8 h-8 bg-slate-200 rounded-full shrink-0 overflow-hidden">
        {comment.author?.avatar_url ? (
          <OptimizedImage
            src={comment.author.avatar_url}
            alt={`Foto profil ${comment.author?.full_name || 'pengguna'}`}
            className="w-full h-full object-cover"
          />
        ) : (
          <OptimizedImage
            src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${comment.author?.full_name || comment.author_id}`}
            alt={`Foto profil ${comment.author?.full_name || 'pengguna'}`}
            className="w-full h-full object-cover"
          />
        )}
      </div>
      <div className="flex-1">
        <div className="bg-slate-50 p-3 rounded-2xl rounded-tl-none border border-slate-100 group relative">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm font-bold text-slate-900">
              {comment.author?.full_name || 'User'}
            </span>
            <span className="text-xs text-slate-500">
              {formatDistanceToNow(new Date(comment.created_at), {
                addSuffix: true,
                locale: localeId,
              })}
            </span>
          </div>

          {editingComment === comment.id ? (
            <form
              onSubmit={(e) => {
                e.preventDefault()
                onSubmit(undefined, comment.parent_id)
              }}
              className="mt-2"
            >
              <textarea
                autoFocus
                value={editContent}
                onChange={(e) => onSetEditContent(e.target.value)}
                className="w-full p-2 bg-white border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                rows={2}
              />
              <div className="flex justify-end gap-2 mt-2">
                <button
                  type="button"
                  onClick={() => onSetEditingComment(null)}
                  className="text-xs text-slate-500 hover:text-slate-700"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="text-xs px-3 py-1 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  Simpan
                </button>
              </div>
            </form>
          ) : (
            <p
              className={cn(
                'text-sm text-slate-700 whitespace-pre-wrap',
                comment.is_deleted && 'text-slate-400 italic'
              )}
            >
              {comment.content}
            </p>
          )}

          {/* Menu */}
          <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1">
            {isAdmin && !comment.is_deleted && (
              <button
                onClick={() => onTogglePin(comment.id, !!comment.is_pinned)}
                className="p-1 text-slate-400 hover:text-blue-600 rounded"
                title={comment.is_pinned ? 'Lepaskan sematan' : 'Sematkan'}
              >
                <Pin
                  className={cn('w-4 h-4', comment.is_pinned && 'fill-blue-500 text-blue-500')}
                />
              </button>
            )}
            {!comment.is_deleted && canManage && (
              <div className="relative">
                <button
                  onClick={() => onSetOpenMenuId(openMenuId === comment.id ? null : comment.id)}
                  className="p-1 text-slate-400 hover:text-slate-600 rounded"
                >
                  <MoreVertical className="w-4 h-4" />
                </button>
                {openMenuId === comment.id && (
                  <div className="absolute right-0 mt-1 w-32 bg-white rounded-lg shadow-lg border border-slate-100 py-1 z-10">
                    {isAuthor && (
                      <button
                        onClick={() => {
                          onSetEditingComment(comment.id)
                          onSetEditContent(comment.content)
                          onSetOpenMenuId(null)
                        }}
                        className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 flex flex-center gap-2"
                      >
                        <Edit2 className="w-3.5 h-3.5" /> Ubah
                      </button>
                    )}
                    <button
                      onClick={() => onDelete(comment.id)}
                      className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 flex items-center gap-2"
                    >
                      <Trash2 className="w-3.5 h-3.5" /> Hapus
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Actions */}
        {!comment.is_deleted && !isReply && (
          <div className="flex items-center gap-4 mt-1 ml-2">
            <button
              onClick={() => onSetReplyingTo(replyingTo === comment.id ? null : comment.id)}
              className="text-xs text-slate-500 font-medium hover:text-blue-600 transition-colors"
            >
              Balas
            </button>
          </div>
        )}

        {/* Reply Input */}
        <AnimatePresence>
          {replyingTo === comment.id && !isReply && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="mt-3 overflow-hidden"
            >
              <form
                onSubmit={(e) => {
                  e.preventDefault()
                  onSubmit(undefined, comment.id)
                }}
                className="flex gap-3"
              >
                <input
                  type="text"
                  autoFocus
                  value={newComment}
                  onChange={(e) => onSetNewComment(e.target.value)}
                  placeholder="Tulis balasan..."
                  className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button
                  type="submit"
                  disabled={!newComment.trim()}
                  className="p-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-50"
                  aria-label="Kirim balasan"
                >
                  <Send className="w-4 h-4" />
                </button>
              </form>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Nested Replies */}
        {comment.replies &&
          comment.replies.map((reply) => (
            <CommentItem
              key={reply.id}
              comment={reply}
              isReply
              userId={userId}
              userRole={userRole}
              editingComment={editingComment}
              editContent={editContent}
              openMenuId={openMenuId}
              replyingTo={replyingTo}
              newComment={newComment}
              onSetEditingComment={onSetEditingComment}
              onSetEditContent={onSetEditContent}
              onSetOpenMenuId={onSetOpenMenuId}
              onSetReplyingTo={onSetReplyingTo}
              onSetNewComment={onSetNewComment}
              onSubmit={onSubmit}
              onDelete={onDelete}
              onTogglePin={onTogglePin}
            />
          ))}
      </div>
    </div>
  )
})

interface CommentSectionProps {
  entityId: string
  entityType: 'announcement' | 'course' | 'lesson'
  className?: string
}

export function CommentSection({ entityId, entityType, className }: CommentSectionProps) {
  const { user, tenantId, role } = useAuth()
  const addToast = useToast((s) => s.addToast)

  const [comments, setComments] = useState<Discussion[]>([])
  const [loading, setLoading] = useState(true)
  const [newComment, setNewComment] = useState('')
  const [replyingTo, setReplyingTo] = useState<string | null>(null)
  const [editingComment, setEditingComment] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')
  const [openMenuId, setOpenMenuId] = useState<string | null>(null)

  const loadComments = useCallback(async () => {
    try {
      const _data = await discussionService.fetchDiscussions({
        tenantId: tenantId!,
        [`${entityType}Id`]: entityId,
        parentId: null, // Fetch top-level comments first
      })

      // Note: For a fully threaded view, we might want to fetch all and format into a tree,
      // or fetch replies on demand. For simplicity, we fetch all for this entity if parentId isn't specified,
      // but let's fetch all and tree-ify them in memory for now.
      const allComments = await discussionService.fetchDiscussions({
        tenantId: tenantId!,
        [`${entityType}Id`]: entityId,
      })

      // Build Tree
      const commentMap = new Map<string, Discussion>()
      const roots: Discussion[] = []

      allComments.forEach((c) => {
        c.replies = []
        commentMap.set(c.id, c)
      })

      allComments.forEach((c) => {
        if (c.parent_id) {
          const parent = commentMap.get(c.parent_id)
          if (parent) {
            parent.replies?.push(c)
          }
        } else {
          roots.push(c)
        }
      })

      setComments(roots)
    } catch (error) {
      if (import.meta.env.DEV) console.error('Error loading comments:', error)
      addToast({ type: 'error', message: 'Gagal memuat komentar' })
    } finally {
      setLoading(false)
    }
  }, [entityId, entityType, addToast])

  useEffect(() => {
    loadComments()
  }, [entityId, entityType, loadComments])

  const handleSubmit = async (e?: React.FormEvent, parentId: string | null = null) => {
    if (e) e.preventDefault()

    const content = parentId ? (editingComment ? editContent : newComment) : newComment
    if (!content.trim() || !user || !tenantId) return

    try {
      await discussionService.saveDiscussion({
        id: editingComment || undefined,
        tenant_id: tenantId,
        author_id: user.id,
        [`${entityType}_id`]: entityId,
        content: content.trim(),
        parent_id: parentId,
      })

      setNewComment('')
      setReplyingTo(null)
      setEditingComment(null)
      setEditContent('')
      // subscription will trigger reload
    } catch {
      addToast({ type: 'error', message: 'Gagal mengirim komentar' })
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Hapus komentar ini?')) return
    try {
      await discussionService.deleteDiscussion(id, tenantId!)
      setOpenMenuId(null)
    } catch {
      addToast({ type: 'error', message: 'Gagal menghapus komentar' })
    }
  }

  const handleTogglePin = useCallback(
    async (id: string, currentPin: boolean) => {
      try {
        await discussionService.togglePin(id, !currentPin, tenantId!)
      } catch {
        addToast({ type: 'error', message: 'Gagal mengubah status sematan komentar' })
      }
    },
    [addToast]
  )

  if (loading) {
    return <div className="py-8 text-center text-slate-500 text-sm">Memuat diskusi...</div>
  }

  return (
    <div className={cn('space-y-6', className)}>
      <div className="flex items-center justify-between">
        <h4 className="font-bold text-slate-800 flex items-center gap-2">
          <MessageSquare className="w-4 h-4 text-blue-500" /> Diskusi & Komentar
        </h4>
        <span className="text-sm font-medium text-slate-500">{comments.length} Komentar</span>
      </div>

      <div className="space-y-4">
        {comments.map((comment) => (
          <CommentItem
            key={comment.id}
            comment={comment}
            userId={user?.id}
            userRole={role}
            editingComment={editingComment}
            editContent={editContent}
            openMenuId={openMenuId}
            replyingTo={replyingTo}
            newComment={newComment}
            onSetEditingComment={setEditingComment}
            onSetEditContent={setEditContent}
            onSetOpenMenuId={setOpenMenuId}
            onSetReplyingTo={setReplyingTo}
            onSetNewComment={setNewComment}
            onSubmit={handleSubmit}
            onDelete={handleDelete}
            onTogglePin={handleTogglePin}
          />
        ))}
        {comments.length === 0 && (
          <p className="text-center text-sm text-slate-500 py-4">
            Belum ada komentar. Jadilah yang pertama!
          </p>
        )}
      </div>

      <form
        onSubmit={(e) => {
          e.preventDefault()
          handleSubmit()
        }}
        className="mt-6 flex gap-3 pt-4 border-t border-slate-100"
      >
        <div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full shrink-0 flex items-center justify-center font-bold text-sm">
          {user?.email?.charAt(0).toUpperCase() || 'U'}
        </div>
        <div className="flex-1 relative">
          <input
            type="text"
            value={replyingTo ? '' : newComment}
            onChange={(e) => !replyingTo && setNewComment(e.target.value)}
            placeholder="Tulis komentar atau pertanyaan..."
            className="w-full pl-4 pr-12 py-2.5 bg-white border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm"
            disabled={!!replyingTo}
          />
          <button
            type="submit"
            disabled={!!replyingTo || !newComment.trim()}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors disabled:opacity-50 disabled:hover:bg-blue-600"
            aria-label="Kirim komentar"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </form>
    </div>
  )
}

