const mockFrom = vi.fn()

vi.mock('@/src/services/api/client', () => ({
  api: {
    from: (...args: unknown[]) => mockFrom(...args),
  },
}))

/**
 * Build a fully chainable API query mock.
 * Every method returns `this` so any chain order works,
 * and `then` makes the object awaitable with the given result.
 */
function makeChain(resolveWith: { data: unknown; error: unknown }) {
  const chain: Record<string, unknown> = {}
  const methods = [
    'select',
    'eq',
    'order',
    'is',
    'or',
    'ilike',
    'range',
    'limit',
    'in',
    'single',
    'maybeSingle',
  ]
  for (const m of methods) {
    chain[m] = vi.fn().mockReturnValue(chain)
  }
  chain.then = (resolve: (value: unknown) => unknown, reject?: (reason: unknown) => unknown) =>
    Promise.resolve(resolveWith).then(resolve, reject)
  return chain
}

describe('announcementService.fetchAnnouncements', () => {
  beforeEach(() => vi.clearAllMocks())

  it('queries announcements table', async () => {
    const chain = makeChain({ data: [], error: null })
    mockFrom.mockReturnValue(chain)
    await announcementService.fetchAnnouncements('tenant-1')
    expect(mockFrom).toHaveBeenCalledWith('announcements')
  })

  it('applies tenant_id filter', async () => {
    const chain = makeChain({ data: [], error: null })
    mockFrom.mockReturnValue(chain)
    await announcementService.fetchAnnouncements('tenant-1')
    expect(chain.eq).toHaveBeenCalledWith('tenant_id', 'tenant-1')
  })

  it('returns announcements on success', async () => {
    const items = [{ id: 'a1', title: 'Test', tenant_id: 'tenant-1' }]
    const chain = makeChain({ data: items, error: null })
    mockFrom.mockReturnValue(chain)
    const result = await announcementService.fetchAnnouncements('tenant-1')
    expect(result).toEqual(items)
  })

  it('throws on error', async () => {
    const chain = makeChain({ data: null, error: { message: 'Access denied' } })
    mockFrom.mockReturnValue(chain)
    await expect(announcementService.fetchAnnouncements('tenant-1')).rejects.toMatchObject({
      message: 'Access denied',
    })
  })

  it('uses course_id filter when provided', async () => {
    const chain = makeChain({ data: [], error: null })
    mockFrom.mockReturnValue(chain)
    await announcementService.fetchAnnouncements('tenant-1', { courseId: 'course-1' })
    expect(chain.or).toHaveBeenCalledWith(`course_id.eq.course-1,course_id.is.null`)
  })
})

import { apiFetch } from '@/src/lib/api'

import { Announcement, AnnouncementRSVP } from '../types'

export const announcementService = {
  /**
   * Fetch announcements for a tenant/user
   */
  async fetchAnnouncements(
    tenantId: string,
    options: {
      courseId?: string
      limit?: number
      offset?: number
      status?: 'draft' | 'published' | 'archived'
      search?: string
    } = {}
  ) {
    let query = apiFetch('/announcements')

    if (options.courseId) {
      query = query.or(`course_id.eq.${options.courseId},course_id.is.null`)
    } else {
      query = query.is('course_id', null)
    }

    if (options.status) {
      query = query.eq('status', options.status)
    } else {
      query = query.eq('status', 'published')
    }

    if (options.search) {
      query = query.ilike('title', `%${options.search}%`)
    }

    if (options.limit) {
      const offset = options.offset || 0
      query = query.range(offset, offset + options.limit - 1)
    }

    const { data, error } = await query

    if (error) {
      if (import.meta.env.DEV) console.error('Error fetching announcements:', error)
      throw error
    }

    return data as unknown as Announcement[]
  },

  /**
   * Get announcement by ID with tenant isolation
   */
  async getAnnouncementById(id: string, tenantId: string) {
    const { data, error } = await apiFetch('/announcements')

    if (error) throw error
    return data as unknown as Announcement
  },

  /**
   * Create or update announcement
   */
  async saveAnnouncement(
    announcement: Partial<Announcement> & { tenant_id: string; created_by: string }
  ) {
    const { data, error } = await apiFetch('/announcements')

    if (error) {
      if (import.meta.env.DEV) console.error('Error saving announcement:', error)
      throw error
    }

    return data as Announcement
  },

  /**
   * Delete announcement with tenant isolation
   */
  async deleteAnnouncement(id: string, tenantId: string) {
    const { error } = await apiFetch('/announcements')

    if (error) throw error
  },

  /**
   * Submit RSVP
   */
  async submitRSVP(
    announcementId: string,
    tenantId: string,
    userId: string,
    response: 'yes' | 'no' | 'maybe'
  ) {
    const { data, error } = await apiFetch('/announcement_rsvps')

    if (error) {
      if (import.meta.env.DEV) console.error('Error submitting RSVP:', error)
      throw error
    }

    return data
  },

  /**
   * Get RSVP status for a user/announcement with tenant isolation
   */
  async getUserRSVP(announcementId: string, userId: string, tenantId: string) {
    const { data, error } = await apiFetch('/announcement_rsvps')

    if (error) throw error
    return data as AnnouncementRSVP | null
  },
}

