import { api, apiFetch } from '@/src/lib/api'

export interface Classroom {
  id: string
  name: string
  course_id?: string
  teacher_id: string
  join_code: string
  max_students?: number
  created_at: string
  teacher_name?: string
  student_count?: number
}

type UserRole = 'teacher' | 'student' | 'admin'

export const classroomService = {
  /**
   * Fetch classrooms based on user role.
   * - teacher: classes they teach
   * - admin: all classes in tenant
   * - student: enrolled classes
   */
  async fetchClassrooms(userId: string, role: UserRole, tenantId: string): Promise<Classroom[]> {
    if (role === 'teacher') {
      const { data, error } = await apiFetch('/classes')
      if (error) throw error
      return data ?? []
    }

    if (role === 'admin') {
      const { data, error } = await apiFetch('/classes')
      if (error) throw error
      return data ?? []
    }

    // Student: fetch via enrollments
    const { data: enrollments, error } = await apiFetch('/enrollments')
    if (error) throw error
    return (enrollments
      ?.map((e) => (e as unknown as { classes: Classroom }).classes)
      .filter(Boolean) ?? []) as Classroom[]
  },

  /**
   * Create a new classroom with auto-generated join code.
   */
  async createClassroom(teacherId: string, name: string, tenantId: string): Promise<void> {
    // SECURITY: Use crypto.getRandomValues() for cryptographically secure join codes to prevent predictability
    const charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    let joinCode = ''
    const randomBytes = new Uint8Array(16)
    while (joinCode.length < 6) {
      globalThis.crypto.getRandomValues(randomBytes)
      for (let i = 0; i < randomBytes.length; i++) {
        // 252 is the highest multiple of 36 < 256 to avoid modulo bias
        if (randomBytes[i] < 252 && joinCode.length < 6) {
          joinCode += charset[randomBytes[i] % 36]
        }
      }
    }
    const { error } = await apiFetch('/classes')
    if (error) throw error
  },

  /**
   * Update classroom name.
   */
  async updateClassroom(id: string, name: string): Promise<void> {
    const { error } = await apiFetch('/classes')
    if (error) throw error
  },

  /**
   * Join a classroom by join code.
   * Note: student_id and tenant_id are inferred by the RPC from auth context.
   */
  async joinClassroom(joinCode: string): Promise<void> {
    const { error } = await apiFetch('/rpc/enroll_student', { method: 'POST', body: JSON.stringify({
          p_join_code: joinCode.toUpperCase(),
        }) })

    if (error) {
      const message = error.message || ''

      if (message.includes('Invalid join code') || error.code === 'P0002') {
        throw new Error('Kode kelas tidak ditemukan')
      }
      if (
        message.includes('Already enrolled') ||
        message.includes('duplicate key value') ||
        message.includes('already exists') ||
        error.code === 'P0003' ||
        error.code === '23505' ||
        error.code === '23514'
      ) {
        throw new Error('Kamu sudah terdaftar di kelas ini')
      }
      if (message.includes('Class is full') || error.code === 'P0004') {
        throw new Error('Kelas sudah penuh')
      }
      if (message.includes('matching the ON CONFLICT specification')) {
        throw new Error('Sistem kelas sedang disinkronkan. Coba gabung lagi beberapa saat lagi.')
      }
      throw new Error('Gagal bergabung dengan kelas. Silakan coba lagi.')
    }
  },

  /**
   * Assign a course to a class.
   */
  async assignCourseToClass(courseId: string, classId: string, tenantId: string): Promise<void> {
    const { error } = await apiFetch('/course_classes')
    if (error) throw error
  },

  /**
   * Unassign a course from a class.
   */
  async unassignCourseFromClass(
    courseId: string,
    classId: string,
    tenantId: string
  ): Promise<void> {
    const { error } = await apiFetch('/course_classes')
    if (error) throw error
  },

  /**
   * Fetch classes assigned to a specific course.
   */
  async fetchAssignedClassesForCourse(courseId: string): Promise<string[]> {
    const { data, error } = await apiFetch('/course_classes')

    if (error) throw error
    return data?.map((item) => item.class_id) || []
  },
  /**
   * Subscribe to realtime classroom changes.
   * Returns cleanup function.
   */
  subscribeToChanges(onUpdate: () => void): () => void {
    const channel = api
      .channel('classrooms-changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'classes' }, onUpdate)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'enrollments' }, onUpdate)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'course_classes' }, onUpdate)
      .subscribe()

    return () => {
      api.removeChannel(channel)
    }
  },

  /**
   * Delete a classroom by ID.
   */
  async deleteClassroom(classId: string): Promise<void> {
    const { error } = await apiFetch('/classes')
    if (error) throw error
  },
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'

import { useAuth } from '@/src/contexts/AuthContext'
import { classroomService } from '@/src/features/classroom/api/classroomService'
import { useClassroom } from '@/src/features/classroom/hooks/useClassroomQueries'
import { useDebounce } from '@/src/hooks/useDebounce'
import { usePageTitle } from '@/src/hooks/usePageTitle'
import { useToast } from '@/src/hooks/useToast'
import { apiFetch } from '@/src/lib/api'

export interface EnrolledStudent {
  id: string
  student_id: string
  full_name: string
  email: string
  enrolled_at: string
  status: string
}

export function useClassManagementState() {
  usePageTitle('Class Management')
  const addToast = useToast((s) => s.addToast)
  const navigate = useNavigate()
  const {
    classrooms,
    addClassroom,
    updateClassroom,
    setActiveClassroomId,
    loading: classLoading,
  } = useClassroom()
  const { tenantId, user } = useAuth()

  const [selectedClassId, setSelectedClassId] = useState<string | null>(null)
  const [students, setStudents] = useState<EnrolledStudent[]>([])
  const [studentCounts, setStudentCounts] = useState<Record<string, number>>({})
  const [loadingStudents, setLoadingStudents] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')

  // Create class
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [newClassName, setNewClassName] = useState('')
  const [isCreating, setIsCreating] = useState(false)

  // Rename
  const [renamingClassId, setRenamingClassId] = useState<string | null>(null)
  const [renameValue, setRenameValue] = useState('')

  // Copy feedback
  const [copiedId, setCopiedId] = useState<string | null>(null)

  // Delete
  const [classToDelete, setClassToDelete] = useState<string | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const selectedClass = classrooms.find((c) => c.id === selectedClassId)

  // Fetch student counts for all classes
  useEffect(() => {
    if (!tenantId || classrooms.length === 0) return

    const fetchCounts = async () => {
      const classIds = classrooms.map((c) => c.id)

      const counts: Record<string, number> = {}
      await Promise.all(
        classIds.map(async (id) => {
          const { count } = await apiFetch('/enrollments')
          counts[id] = count ?? 0
        })
      )

      setStudentCounts(counts)
    }
    fetchCounts()
  }, [classrooms, tenantId])

  // Fetch enrolled students for selected class
  const fetchStudents = useCallback(
    async (classId: string) => {
      if (!tenantId) return
      setLoadingStudents(true)
      try {
        const { data: enrollmentData, error: enrollmentError } = await apiFetch('/enrollments')
        if (enrollmentError) throw enrollmentError

        setStudents(
          (enrollmentData || []).map(
            (e: {
              id: string
              joined_at: string
              student:
                | { id: string; full_name: string; email: string }
                | { id: string; full_name: string; email: string }[]
            }) => {
              const student = Array.isArray(e.student) ? e.student[0] : e.student
              return {
                id: e.id,
                student_id: student?.id ?? '',
                full_name: student?.full_name || 'Unnamed',
                email: student?.email || '-',
                enrolled_at: e.joined_at,
                status: 'ACTIVE' as const,
              }
            }
          )
        )
      } catch (err) {
        if (import.meta.env.DEV) console.error('Failed to fetch students:', err)
        setStudents([])
      } finally {
        setLoadingStudents(false)
      }
    },
    [tenantId]
  )

  useEffect(() => {
    if (selectedClassId) fetchStudents(selectedClassId)
  }, [selectedClassId, fetchStudents])

  // Auto-select first class
  useEffect(() => {
    if (!selectedClassId && classrooms.length > 0) {
      setSelectedClassId(classrooms[0].id)
    }
  }, [classrooms, selectedClassId])

  const handleCreateClass = async () => {
    if (!newClassName.trim()) return
    setIsCreating(true)
    try {
      await addClassroom(newClassName.trim())
      setNewClassName('')
      setShowCreateForm(false)
    } catch (err: unknown) {
      addToast({
        type: 'error',
        message:
          'Gagal membuat kelas: ' +
          (err instanceof Error ? err.message : 'Kesalahan tidak diketahui'),
      })
    } finally {
      setIsCreating(false)
    }
  }

  const handleRename = async (classId: string) => {
    if (!renameValue.trim()) return
    try {
      await updateClassroom(classId, renameValue.trim())
      setRenamingClassId(null)
    } catch (err: unknown) {
      addToast({
        type: 'error',
        message:
          'Gagal mengubah nama: ' +
          (err instanceof Error ? err.message : 'Kesalahan tidak diketahui'),
      })
    }
  }

  const confirmDeleteClass = async () => {
    if (!classToDelete) return

    setIsDeleting(true)
    try {
      await classroomService.deleteClassroom(classToDelete)
      if (selectedClassId === classToDelete) setSelectedClassId(null)
      setClassToDelete(null)
    } catch (err: unknown) {
      addToast({
        type: 'error',
        message:
          'Gagal menghapus kelas: ' +
          (err instanceof Error ? err.message : 'Kesalahan tidak diketahui'),
      })
    } finally {
      setIsDeleting(false)
    }
  }

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text)
    setCopiedId(id)
    setTimeout(() => setCopiedId(null), 2000)
  }

  const handleRemoveStudent = async (student: EnrolledStudent) => {
    if (!confirm(`Keluarkan ${student.full_name} dari kelas ini?`)) return
    try {
      const { error } = await apiFetch('/enrollments')
      if (error) throw error
      // Refresh student list
      fetchStudents(selectedClassId!)
      // Update count
      setStudentCounts((prev) => ({
        ...prev,
        [selectedClassId!]: Math.max((prev[selectedClassId!] || 1) - 1, 0),
      }))
    } catch (err: unknown) {
      addToast({
        type: 'error',
        message:
          'Gagal mengeluarkan siswa: ' +
          (err instanceof Error ? err.message : 'Kesalahan tidak diketahui'),
      })
    }
  }

  const debouncedSearch = useDebounce(searchQuery, 300)

  const filteredClassrooms = useMemo(
    () => classrooms.filter((c) => c.name.toLowerCase().includes(debouncedSearch.toLowerCase())),
    [classrooms, debouncedSearch]
  )

  return {
    // Data
    classrooms,
    filteredClassrooms,
    selectedClass,
    selectedClassId,
    students,
    studentCounts,
    classLoading,
    loadingStudents,
    searchQuery,

    // Create form
    showCreateForm,
    newClassName,
    isCreating,

    // Rename
    renamingClassId,
    renameValue,

    // Copy
    copiedId,

    // Delete
    classToDelete,
    isDeleting,

    // Actions
    navigate,
    setSelectedClassId,
    setSearchQuery,
    setShowCreateForm,
    setNewClassName,
    setRenamingClassId,
    setRenameValue,
    setClassToDelete,
    setActiveClassroomId,
    handleCreateClass,
    handleRename,
    confirmDeleteClass,
    handleCopy,
    handleRemoveStudent,
  }
}

