import { api } from '@/src/lib/api'
import { useCallback, useEffect, useRef, useState } from 'react'

import type { BuilderAction } from './builderReducer'

export type ChannelStatus = 'connecting' | 'connected' | 'disconnected'

export interface BroadcastPayload {
  action: BuilderAction
  userId: string
  userName: string
}

export function useBuilderChannel(
  courseId: string | null,
  userId: string | null,
  dispatch: React.Dispatch<BuilderAction>,
  onReconnect?: () => void
) {
  const channelRef = useRef<any | null>(null)
  const [channelStatus, setChannelStatus] = useState<ChannelStatus>('disconnected')

  // Subscribe to channel when courseId is available
  useEffect(() => {
    if (!courseId || !userId) return

    const channel = api.channel(`builder:${courseId}`, {
      config: { broadcast: { self: false } },
    })

    channel
      .on('broadcast', { event: 'builder_action' }, (payload) => {
        const data = payload.payload as BroadcastPayload
        if (data.userId === userId) return // ignore own broadcasts

        // Map to REMOTE_* action types
        const remoteAction = mapToRemoteAction(data.action)
        if (remoteAction) {
          dispatch(remoteAction)
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          setChannelStatus('connected')
        } else if (status === 'CLOSED' || status === 'CHANNEL_ERROR') {
          setChannelStatus('disconnected')
        } else {
          setChannelStatus('connecting')
        }
      })

    channelRef.current = channel

    return () => {
      channel.unsubscribe()
      channelRef.current = null
      setChannelStatus('disconnected')
    }
  }, [courseId, userId, dispatch, onReconnect])

  // Broadcast an action to other clients
  const broadcast = useCallback(
    (action: BuilderAction, userName: string) => {
      if (!channelRef.current || !userId) return
      channelRef.current.send({
        type: 'broadcast',
        event: 'builder_action',
        payload: { action, userId, userName } satisfies BroadcastPayload,
      })
    },
    [userId]
  )

  return { channelRef, channelStatus, broadcast }
}

/**
 * Maps a local BuilderAction to its REMOTE_* equivalent.
 * Remote actions bypass undo/redo history.
 */
function mapToRemoteAction(action: BuilderAction): BuilderAction | null {
  switch (action.type) {
    case 'ADD_MODULE':
      return { ...action, type: 'REMOTE_ADD_MODULE' }
    case 'UPDATE_MODULE':
      return { ...action, type: 'REMOTE_UPDATE_MODULE' }
    case 'DELETE_MODULE':
      return { ...action, type: 'REMOTE_DELETE_MODULE' }
    case 'SET_MODULES':
      return { ...action, type: 'REMOTE_SET_MODULES' }
    case 'ADD_LESSON':
      return { ...action, type: 'REMOTE_ADD_LESSON' }
    case 'UPDATE_LESSON':
      return { ...action, type: 'REMOTE_UPDATE_LESSON' }
    case 'DELETE_LESSON':
      return { ...action, type: 'REMOTE_DELETE_LESSON' }
    case 'ADD_BLOCK':
      return { ...action, type: 'REMOTE_ADD_BLOCK' }
    case 'UPDATE_BLOCK':
      return { ...action, type: 'REMOTE_UPDATE_BLOCK' }
    case 'DELETE_BLOCK':
      return { ...action, type: 'REMOTE_DELETE_BLOCK' }
    case 'SET_BLOCKS':
      return { ...action, type: 'REMOTE_SET_BLOCKS' }
    default:
      return null
  }
}

type RealtimeChannel = any
import { useCallback, useEffect, useRef, useState } from 'react'

export interface PresenceData {
  userId: string
  fullName: string
  avatarUrl: string | null
  activeBlockId: string | null
  color: string
  onlineAt: string
}

// Deterministic color assignment from user ID
const PRESENCE_COLORS = [
  '#ef4444',
  '#f97316',
  '#eab308',
  '#22c55e',
  '#06b6d4',
  '#3b82f6',
  '#8b5cf6',
  '#ec4899',
]

function getColorForUser(userId: string): string {
  let hash = 0
  for (let i = 0; i < userId.length; i++) {
    hash = ((hash << 5) - hash + userId.charCodeAt(i)) | 0
  }
  return PRESENCE_COLORS[Math.abs(hash) % PRESENCE_COLORS.length]
}

export function useBuilderPresence(
  channelRef: React.RefObject<RealtimeChannel | null>,
  userId: string | null,
  fullName: string,
  avatarUrl: string | null
) {
  const [others, setOthers] = useState<Map<string, PresenceData>>(new Map())
  const myPresenceRef = useRef<Partial<PresenceData>>({})

  // Track presence
  useEffect(() => {
    const channel = channelRef.current
    if (!channel || !userId) return

    const myColor = getColorForUser(userId)

    channel.on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState<PresenceData>()
      const newOthers = new Map<string, PresenceData>()
      for (const [, presences] of Object.entries(state)) {
        for (const p of presences) {
          if (p.userId !== userId) {
            newOthers.set(p.userId, p as unknown as PresenceData)
          }
        }
      }
      setOthers(newOthers)
    })

    // Track my presence
    channel.track({
      userId,
      fullName,
      avatarUrl,
      activeBlockId: null,
      color: myColor,
      onlineAt: new Date().toISOString(),
    } satisfies PresenceData)

    return () => {
      channel.untrack()
    }
  }, [channelRef, userId, fullName, avatarUrl])

  // Update which block I'm editing
  const updateActiveBlock = useCallback(
    (blockId: string | null) => {
      const channel = channelRef.current
      if (!channel || !userId) return
      myPresenceRef.current.activeBlockId = blockId
      channel.track({
        userId,
        fullName,
        avatarUrl,
        activeBlockId: blockId,
        color: getColorForUser(userId),
        onlineAt: new Date().toISOString(),
      } satisfies PresenceData)
    },
    [channelRef, userId, fullName, avatarUrl]
  )

  // Check if a block is locked by another user
  const getBlockLocker = useCallback(
    (blockId: string): PresenceData | null => {
      for (const [, p] of others) {
        if (p.activeBlockId === blockId) return p
      }
      return null
    },
    [others]
  )

  return {
    others,
    updateActiveBlock,
    getBlockLocker,
    othersArray: Array.from(others.values()),
  }
}

