   * Vote on a discussion post (fire-and-forget).
   */
  async voteDiscussion(discussionId: string): Promise<void> {
    await apiFetch('/rpc/vote_discussion', { method: 'POST', body: JSON.stringify({ p_discussion_id: discussionId }) })
  },

