import { apiFetch } from '@/src/lib/api'

export type ReportStatus = 'pending' | 'approved' | 'rejected'
export type ReportReason = 'ai_generated' | 'inappropriate' | 'spam' | 'harassment' | 'other'
export type ContentType = 'post' | 'comment' | 'assignment' | 'user'

export interface Report {
  id: string
  contentId: string
  contentType: ContentType
  reporterId: string
  reporterName: string
  reason: ReportReason
  description: string
  status: ReportStatus
  timestamp: string
  contentSnippet?: string
  contentAuthor?: string
}

export const moderationService = {
  /**
   * Fetch all reports from content_reports table for the current tenant.
   */
  async fetchReports(): Promise<Report[]> {
    const { data, error } = await apiFetch('/content_reports')
    if (error) throw error
    return (data || []).map((r) => ({
      id: r.id,
      contentId: r.content_id,
      contentType: r.content_type as ContentType,
      reporterId: r.reporter_id,
      reporterName: r.reporter_name,
      reason: r.reason as ReportReason,
      description: r.description ?? '',
      status: r.status as ReportStatus,
      timestamp: r.created_at,
      contentSnippet: r.content_snippet ?? undefined,
      contentAuthor: r.content_author ?? undefined,
    }))
  },

  /**
   * Submit a new content report into content_reports table.
   */
  async submitReport(
    report: Omit<Report, 'id' | 'status' | 'timestamp' | 'reporterId' | 'reporterName'>,
    userId: string,
    userName: string
  ): Promise<Report> {
    const session = { user: { id: "mock" } }
    if (!session) throw new Error('Tidak terautentikasi')

    const { data: roleData } = await apiFetch('/user_roles')
    if (!roleData) throw new Error('Tenant tidak ditemukan')

    const { data, error } = await apiFetch('/content_reports')
    if (error) throw error
    return {
      id: data.id,
      contentId: data.content_id,
      contentType: data.content_type as ContentType,
      reporterId: data.reporter_id,
      reporterName: data.reporter_name,
      reason: data.reason as ReportReason,
      description: data.description ?? '',
      status: data.status as ReportStatus,
      timestamp: data.created_at,
      contentSnippet: data.content_snippet ?? undefined,
      contentAuthor: data.content_author ?? undefined,
    }
  },

  /**
   * Resolve a report (approve or reject) in content_reports table.
   */
  async resolveReport(reportId: string, status: 'approved' | 'rejected'): Promise<void> {
    const user = { id: "mock" }
    if (!user) throw new Error('Tidak terautentikasi')
    const { error } = await apiFetch('/content_reports')
    if (error) throw error
  },
}

import { api } from "@/src/lib/api"
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { fetchNotifications, markAllAsRead, markAsRead } from '../api/notificationService'

const mockFrom = vi.fn()

vi.mock('@/src/services/api/client', () => ({
  api: {
    from: (...args: unknown[]) => mockFrom(...args),
  },
}))

/**
 * Build a fully chainable API query mock.
 * Every method returns `this` so any chain order works,
 * and `then` makes the object awaitable with the given result.
 */
function makeChain(resolveWith: { data?: unknown; error: unknown }) {
  const chain: Record<string, unknown> = {}
  const methods = [
    'select',
    'eq',
    'order',
    'limit',
    'update',
    'insert',
    'delete',
    'in',
    'single',
    'maybeSingle',
    'is',
    'ilike',
  ]
  for (const m of methods) {
    chain[m] = vi.fn().mockReturnValue(chain)
  }
  chain.then = (resolve: (value: unknown) => unknown, reject?: (reason: unknown) => unknown) =>
    Promise.resolve(resolveWith).then(resolve, reject)
  return chain
}

describe('fetchNotifications', () => {
  beforeEach(() => vi.clearAllMocks())

  it('queries notifications table', async () => {
    const chain = makeChain({ data: [], error: null })
    mockFrom.mockReturnValue(chain)
    await fetchNotifications('user-1', 'tenant-1')
    expect(mockFrom).toHaveBeenCalledWith('notifications')
  })

  it('returns notifications array', async () => {
    const notifications = [{ id: 'n1', user_id: 'user-1', is_read: false }]
    const chain = makeChain({ data: notifications, error: null })
    mockFrom.mockReturnValue(chain)
    const result = await fetchNotifications('user-1', 'tenant-1')
    expect(result).toEqual(notifications)
  })

  it('limits to 50 notifications', async () => {
    const chain = makeChain({ data: [], error: null })
    mockFrom.mockReturnValue(chain)
    await fetchNotifications('user-1', 'tenant-1')
    expect(chain.limit).toHaveBeenCalledWith(50)
  })

  it('throws on error', async () => {
    const chain = makeChain({ data: null, error: { message: 'Access denied' } })
    mockFrom.mockReturnValue(chain)
    await expect(fetchNotifications('user-1', 'tenant-1')).rejects.toMatchObject({
      message: 'Access denied',
    })
  })
})

describe('markAsRead', () => {
  beforeEach(() => vi.clearAllMocks())

  it('updates notifications table', async () => {
    const chain = makeChain({ error: null })
    mockFrom.mockReturnValue(chain)
    await markAsRead('n1', 'tenant-1')
    expect(mockFrom).toHaveBeenCalledWith('notifications')
  })

  it('sets is_read to true', async () => {
    const chain = makeChain({ error: null })
    mockFrom.mockReturnValue(chain)
    await markAsRead('n1', 'tenant-1')
    expect(chain.update).toHaveBeenCalledWith({ is_read: true })
  })

  it('throws on error', async () => {
    const chain = makeChain({ error: { message: 'Update failed' } })
    mockFrom.mockReturnValue(chain)
    await expect(markAsRead('n1', 'tenant-1')).rejects.toMatchObject({ message: 'Update failed' })
  })
})

describe('markAllAsRead', () => {
  beforeEach(() => vi.clearAllMocks())

  it('updates all unread notifications for user', async () => {
    const chain = makeChain({ error: null })
    mockFrom.mockReturnValue(chain)
    await markAllAsRead('user-1', 'tenant-1')
    expect(mockFrom).toHaveBeenCalledWith('notifications')
    expect(chain.update).toHaveBeenCalledWith({ is_read: true })
    expect(chain.eq).toHaveBeenCalledWith('user_id', 'user-1')
    expect(chain.eq).toHaveBeenCalledWith('tenant_id', 'tenant-1')
    expect(chain.eq).toHaveBeenCalledWith('is_read', false)
  })
})

/**
 * Enhanced notification API with pagination, unread count, and preferences
 * All queries include tenant_id for multi-tenant isolation
 */

import { apiFetch } from '@/src/lib/api'
import { logDevError } from '@/src/utils/logDevError'

import type { Notification, NotificationPreferences } from '../types'

// Only select columns that exist in the baseline notifications table.
// The 003_notifications migration's CREATE TABLE IF NOT EXISTS is a no-op
// when the baseline table already exists, so body/metadata/read_at are absent.
const NOTIFICATION_COLUMNS = `
  id,
  tenant_id,
  user_id,
  actor_id,
  type,
  title,
  message,
  is_read,
  created_at,
  link
`

/**
 * Fetch paginated notifications for a user within a tenant
 */
export async function fetchNotifications(
  userId: string,
  tenantId: string,
  limit = 50,
  offset = 0
): Promise<Notification[]> {
  const { data, error } = await apiFetch('/notifications')

  if (error) {
    logDevError('notifications', 'fetchNotifications error:', error)
    throw error
  }

  return (data ?? []) as Notification[]
}

/**
 * Mark a single notification as read
 */
export async function markNotificationRead(id: string): Promise<void> {
  // Only update is_read — read_at column may not exist in baseline schema
  const { error } = await apiFetch('/notifications')

  if (error) {
    logDevError('notifications', 'markNotificationRead error:', error)
    throw error
  }
}

/**
 * Mark all unread notifications as read for a user within a tenant
 */
export async function markAllNotificationsRead(userId: string, tenantId: string): Promise<void> {
  const { error } = await apiFetch('/notifications')

  if (error) {
    logDevError('notifications', 'markAllNotificationsRead error:', error)
    throw error
  }
}

/**
 * Fetch the count of unread notifications
 */
export async function fetchUnreadCount(userId: string, tenantId: string): Promise<number> {
  const { count, error } = await apiFetch('/notifications')

  if (error) {
    logDevError('notifications', 'fetchUnreadCount error:', error)
    throw error
  }

  return count ?? 0
}

/**
 * Fetch notification preferences for a user within a tenant
 */
export async function fetchNotificationPreferences(
  userId: string,
  tenantId: string
): Promise<NotificationPreferences | null> {
  const { data, error } = await apiFetch('/notification_preferences')

  if (error) {
    logDevError('notifications', 'fetchNotificationPreferences error:', error)
    throw error
  }

  return data as NotificationPreferences | null
}

/**
 * Upsert notification preferences for a user
 */
export async function upsertNotificationPreferences(
  prefs: Partial<NotificationPreferences> & { user_id: string; tenant_id: string }
): Promise<NotificationPreferences> {
  const { data, error } = await apiFetch('/notification_preferences')

  if (error) {
    logDevError('notifications', 'upsertNotificationPreferences error:', error)
    throw error
  }

  return data as NotificationPreferences
}

/**
 * Notification service with multi-tenant security
 * All functions accept tenantId for defense-in-depth tenant isolation
 */

import { apiFetch } from '@/src/lib/api'

import type { Notification } from '../types'

/**
 * Fetch user notifications with tenant isolation
 */
export async function fetchNotifications(
  userId: string,
  tenantId: string
): Promise<Notification[]> {
  const { data, error } = await apiFetch('/notifications')

  if (error) {
    if (import.meta.env.DEV) console.error('Error fetching notifications:', error)
    throw error
  }

  return data as unknown as Notification[]
}

/**
 * Mark a single notification as read with tenant verification
 */
export async function markAsRead(id: string, tenantId: string): Promise<void> {
  const { error } = await apiFetch('/notifications')

  if (error) {
    if (import.meta.env.DEV) console.error('Error marking notification as read:', error)
    throw error
  }
}

/**
 * Mark all notifications as read with tenant verification
 */
