import { api } from "@/src/lib/api"
import 'katex/dist/katex.min.css'

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { MessageSquare } from 'lucide-react'
import { useMemo, useState } from 'react'

import { ReportModal } from '@/src/components/moderation/ReportModal'
import { EmptyState } from '@/src/components/ui'
import { useAuth } from '@/src/contexts/AuthContext'
import { discussionService } from '@/src/features/discussions/api/discussionService'
import {
  CreatePostForm,
  ForumHeader,
  ForumSearchBar,
  PostItem,
} from '@/src/features/discussions/components/forum'
import { buildForumPosts } from '@/src/features/discussions/utils/forumUtils'
import { useStudentXPProfile } from '@/src/features/gamification/queries/gamificationQueries'
import { useSubmitReport } from '@/src/features/moderation/queries/moderationQueries'
import { useDebounce } from '@/src/hooks/useDebounce'
import { usePageTitle } from '@/src/hooks/usePageTitle'

export function Forum() {
  usePageTitle('Forum')
  const { role, user, tenantId, profile } = useAuth()
  const queryClient = useQueryClient()
  const submitReport = useSubmitReport()
  const isTeacher = role === 'teacher'

  const { data: xpProfile } = useStudentXPProfile(user?.id)

  const { data: rawDiscussions = [] } = useQuery({
    queryKey: ['forum-posts', tenantId],
    queryFn: () => discussionService.fetchForumPosts(tenantId!),
    enabled: !!tenantId,
  })

  const posts = useMemo(() => buildForumPosts(rawDiscussions), [rawDiscussions])

  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('Semua')
  const [isAnonymous, setIsAnonymous] = useState(false)

  // ⚡ Perf: Debounce search input to avoid re-filtering on every keystroke
  const debouncedSearch = useDebounce(searchQuery, 300)

  const [reportModal, setReportModal] = useState<{
    isOpen: boolean
    contentId: string
    contentType: 'post' | 'comment'
    contentSnippet?: string
    contentAuthor?: string
  }>({
    isOpen: false,
    contentId: '',
    contentType: 'post',
  })

  const createPost = useMutation({
    mutationFn: async (vars: {
      title: string
      content: string
      category: string
      isAnon: boolean
    }) => {
      if (!user || !tenantId) throw new Error('Not authenticated')
      return discussionService.saveDiscussion({
        tenant_id: tenantId,
        author_id: user.id,
        content: vars.content,
        title: vars.title,
        category: vars.category,
        is_anonymous: vars.isAnon,
        is_pinned: false,
        is_edited: false,
        is_deleted: false,
      })
    },
    onSuccess: (data, vars) => {
      const isAiSuspect =
        vars.content.length > 200 &&
        (vars.content.includes('tentu') || vars.content.includes('sebagai model bahasa'))
      if (isAiSuspect) {
        const authorName = vars.isAnon ? 'Anonim' : (profile?.first_name ?? 'Pengguna')
        submitReport.mutate({
          contentId: data.id,
          contentType: 'post',
          reason: 'ai_generated',
          description:
            'Terdeteksi otomatis oleh sistem AI Shield sebagai konten yang berpotensi dibuat oleh AI.',
          contentSnippet: vars.content.substring(0, 100) + '...',
          contentAuthor: authorName,
        })
      }
      queryClient.invalidateQueries({ queryKey: ['forum-posts', tenantId] })
      setIsAnonymous(false)
    },
  })

  const handleReport = (id: string, type: 'post' | 'comment', snippet: string, author: string) => {
    setReportModal({
      isOpen: true,
      contentId: id,
      contentType: type,
      contentSnippet: snippet,
      contentAuthor: author,
    })
  }

  const handleMarkBestAnswer = async (postId: string, commentId: string) => {
    await discussionService.setBestAnswer(postId, commentId, tenantId!)
    queryClient.invalidateQueries({ queryKey: ['forum-posts', tenantId] })
  }

  // ⚡ Perf: Memoize filteredPosts — was recomputed on every render without useMemo
  const filteredPosts = useMemo(
    () =>
      posts.filter((post) => {
        const matchesSearch =
          post.title.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
          post.content.toLowerCase().includes(debouncedSearch.toLowerCase())
        const matchesCategory = selectedCategory === 'Semua' || post.category === selectedCategory
        return matchesSearch && matchesCategory
      }),
    [posts, debouncedSearch, selectedCategory]
  )

  const myAvatar = isAnonymous
    ? 'https://api.dicebear.com/7.x/avataaars/svg?seed=Anon'
    : (profile?.avatar_url ??
      `https://api.dicebear.com/7.x/avataaars/svg?seed=${user?.id ?? 'user'}`)

  return (
    <div className="max-w-4xl mx-auto space-y-6 flex-1 w-full p-4 md:p-8">
      <ForumHeader knowledgePoints={xpProfile?.total_xp ?? 0} />

      <ForumSearchBar
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        selectedCategory={selectedCategory}
        onCategoryChange={setSelectedCategory}
      />

      <CreatePostForm
        onSubmit={(data) => createPost.mutate(data)}
        isPending={createPost.isPending}
        avatar={myAvatar}
        isAnonymous={isAnonymous}
        onAnonymousChange={setIsAnonymous}
      />

      {/* Feed */}
      <div className="space-y-6">
        {filteredPosts.length > 0 ? (
          filteredPosts.map((post) => (
            <PostItem
              key={post.id}
              post={post}
              isTeacher={isTeacher}
              onMarkBest={handleMarkBestAnswer}
              onReport={handleReport}
            />
          ))
        ) : (
          <EmptyState
            icon={<MessageSquare className="w-12 h-12" />}
            title="Belum ada diskusi"
            description="Jadilah yang pertama membuka diskusi di forum ini."
          />
        )}
      </div>

      <ReportModal
        isOpen={reportModal.isOpen}
        onClose={() => setReportModal((prev) => ({ ...prev, isOpen: false }))}
        contentId={reportModal.contentId}
        contentType={reportModal.contentType}
        contentSnippet={reportModal.contentSnippet}
        contentAuthor={reportModal.contentAuthor}
      />
    </div>
  )
}

import { AlertTriangle, Loader2 } from 'lucide-react'
import { useEffect, useState } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'

import { api, apiFetch } from '@/src/lib/api'

// ==========================================================================
// LtiCallback — Handles the redirect after LTI launch
//
// Receives a magic link token from the lti-launch Edge Function,
// verifies it via API OTP, and redirects to the target lesson/course.
//
// Route: /#/lti/callback?token=...&type=magiclink&redirect=...
// ==========================================================================

type CallbackState = 'verifying' | 'success' | 'error'

export function LtiCallback() {
  const [searchParams] = useSearchParams()
  const navigate = useNavigate()
  const [state, setState] = useState<CallbackState>('verifying')
  const [errorMessage, setErrorMessage] = useState('')

  useEffect(() => {
    async function verifyToken() {
      const token = searchParams.get('token')
      const type = searchParams.get('type') || 'magiclink'
      const redirect = searchParams.get('redirect') || '/app/student/courses'

      if (!token) {
        setState('error')
        setErrorMessage(
          'Token autentikasi tidak ditemukan. Silakan coba lagi dari platform LMS Anda.'
        )
        return
      }

      try {
        // Verify the OTP token to establish a API session
        const { data, error } = await api.auth.verifyOtp({
          token_hash: token,
          type: type as 'magiclink',
        })

        if (error) {
          console.error('[LtiCallback] OTP verification failed:', error)
          setState('error')

          if (error.message?.includes('expired')) {
            setErrorMessage('Link sudah kadaluarsa. Silakan coba lagi dari platform LMS Anda.')
          } else if (error.message?.includes('invalid')) {
            setErrorMessage('Token tidak valid. Silakan coba lagi dari platform LMS Anda.')
          } else {
            setErrorMessage(`Gagal memverifikasi sesi: ${error.message}`)
          }
          return
        }

        if (!data.session) {
          setState('error')
          setErrorMessage('Sesi tidak dapat dibuat. Silakan coba lagi.')
          return
        }

        setState('success')

        // Short delay to show success state, then redirect
        setTimeout(() => {
          // Navigate to the target page
          // The redirect path from LTI launch may be a full URL or a relative path
          try {
            const url = new URL(redirect, window.location.origin)
            // If it's an internal path, use navigate
            if (url.origin === window.location.origin) {
              const path = url.pathname + url.search + url.hash
              navigate(path, { replace: true })
            } else {
              // External redirect (shouldn't happen, but handle gracefully)
              navigate('/app/student/courses', { replace: true })
            }
          } catch {
            // If redirect is a relative path
            navigate(redirect, { replace: true })
          }
        }, 500)
      } catch (err) {
        console.error('[LtiCallback] Unexpected error:', err)
        setState('error')
        setErrorMessage('Terjadi kesalahan yang tidak terduga. Silakan coba lagi.')
      }
    }

    verifyToken()
  }, [searchParams, navigate])

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
      <div className="max-w-md w-full mx-4">
        <div className="bg-white dark:bg-slate-900 rounded-xl shadow-lg border border-slate-200 dark:border-slate-800 p-8 text-center">
          {/* Logo / Header */}
          <div className="mb-6">
            <h1 className="text-xl font-bold text-slate-900 dark:text-white">EduSync LTI</h1>
            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
              Integrasi Platform Pembelajaran
            </p>
          </div>

          {state === 'verifying' && (
            <div className="flex flex-col items-center gap-4">
              <Loader2 className="h-10 w-10 text-blue-500 animate-spin" />
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Memverifikasi sesi Anda...
              </p>
            </div>
          )}

          {state === 'success' && (
            <div className="flex flex-col items-center gap-4">
              <div className="h-10 w-10 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
                <svg
                  className="h-6 w-6 text-emerald-600 dark:text-emerald-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={2}
                >
                  <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Berhasil! Mengalihkan ke materi...
              </p>
            </div>
          )}

          {state === 'error' && (
            <div className="flex flex-col items-center gap-4">
              <div className="h-10 w-10 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center">
                <AlertTriangle className="h-6 w-6 text-red-600 dark:text-red-400" />
              </div>
              <div>
                <p className="font-medium text-red-700 dark:text-red-400 mb-1">Verifikasi Gagal</p>
                <p className="text-sm text-slate-500 dark:text-slate-400">{errorMessage}</p>
              </div>
              <button
                onClick={() => navigate('/login', { replace: true })}
                className="mt-2 inline-flex items-center px-4 py-2 text-sm font-medium rounded-lg
                           bg-slate-100 text-slate-700 hover:bg-slate-200
                           dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700
                           transition-colors"
              >
                Ke Halaman Login
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

