          )}
        </div>

        {/* PDDIKTI Status Card */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm md:col-span-2">
          <div className="flex items-center justify-between mb-6">
