import type { FeatureFlag } from '../featureFlags'
import {
  invalidateFlagCache,
  isFeatureEnabled,
  loadFeatureFlags,
  useFeatureFlag,
} from '../featureFlags'

// Access mock helpers
const apiMock = await import('@/src/services/api/client')
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const mockSelect: ReturnType<typeof vi.fn> = (apiMock as any).__mockSelect

async function seedFlags(flags: FeatureFlag[]) {
  invalidateFlagCache()
  mockSelect.mockResolvedValueOnce({ data: flags, error: null })
  await loadFeatureFlags()
}

describe('featureFlags', () => {
  beforeEach(() => {
    invalidateFlagCache()
    vi.clearAllMocks()
  })

  describe('isFeatureEnabled', () => {
    it('returns false when cache is not loaded', () => {
      expect(isFeatureEnabled('any_flag')).toBe(false)
    })

    it('returns false when flag does not exist in cache', async () => {
      await seedFlags([])
      expect(isFeatureEnabled('nonexistent')).toBe(false)
    })

    it('returns false when flag.enabled is false', async () => {
      await seedFlags([
        { flag_name: 'my_flag', enabled: false, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(isFeatureEnabled('my_flag')).toBe(false)
    })

    it('returns true when flag is enabled with 100% rollout', async () => {
      await seedFlags([
        { flag_name: 'my_flag', enabled: true, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(isFeatureEnabled('my_flag')).toBe(true)
    })

    it('returns true when tenantId is in tenant_ids whitelist', async () => {
      await seedFlags([
        {
          flag_name: 'beta',
          enabled: true,
          tenant_ids: ['tenant-A', 'tenant-B'],
          rollout_percentage: 0,
        },
      ])
      expect(isFeatureEnabled('beta', 'tenant-A')).toBe(true)
    })

    it('returns false when tenantId is NOT in tenant_ids whitelist', async () => {
      await seedFlags([
        {
          flag_name: 'beta',
          enabled: true,
          tenant_ids: ['tenant-A'],
          rollout_percentage: 100,
        },
      ])
      expect(isFeatureEnabled('beta', 'tenant-X')).toBe(false)
    })

    it('uses deterministic rollout hash when no tenant_ids', async () => {
      await seedFlags([
        { flag_name: 'my_flag', enabled: true, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(isFeatureEnabled('my_flag')).toBe(true)

      invalidateFlagCache()
      mockSelect.mockResolvedValueOnce({
        data: [{ flag_name: 'my_flag', enabled: true, tenant_ids: [], rollout_percentage: 0 }],
        error: null,
      })
      await loadFeatureFlags()
      // 0% rollout → hash % 100 (any value) is never < 0
      expect(isFeatureEnabled('my_flag')).toBe(false)
    })
  })

  describe('useFeatureFlag', () => {
    it('returns false when cache is empty', () => {
      expect(useFeatureFlag('offline_quiz')).toBe(false)
    })

    it('returns false for unknown flag', async () => {
      await seedFlags([
        { flag_name: 'other', enabled: true, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(useFeatureFlag('offline_quiz')).toBe(false)
    })

    it('returns true when flag.enabled is true', async () => {
      await seedFlags([
        { flag_name: 'offline_quiz', enabled: true, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(useFeatureFlag('offline_quiz')).toBe(true)
    })

    it('returns false when flag.enabled is false', async () => {
      await seedFlags([
        { flag_name: 'offline_quiz', enabled: false, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(useFeatureFlag('offline_quiz')).toBe(false)
    })
  })

  describe('invalidateFlagCache', () => {
    it('clears loaded cache', async () => {
      await seedFlags([
        { flag_name: 'my_flag', enabled: true, tenant_ids: [], rollout_percentage: 100 },
      ])
      expect(useFeatureFlag('my_flag')).toBe(true)

      invalidateFlagCache()
      expect(useFeatureFlag('my_flag')).toBe(false)
    })
  })

  describe('loadFeatureFlags', () => {
    it('does not re-fetch within TTL', async () => {
      await seedFlags([{ flag_name: 'f', enabled: true, tenant_ids: [], rollout_percentage: 100 }])
      // Second call should NOT trigger another select (cache still warm)
      await loadFeatureFlags()
      expect(mockSelect).toHaveBeenCalledTimes(1)
    })
  })
})

// EduSync LMS — Background Sync
// Processes the offline sync queue when connectivity is restored

import { apiFetch } from '@/src/lib/api'

import { getPendingSubmissions, markSynced } from './offlineStorage'

// Exponential back-off delays: 1 s → 5 s → 30 s → 5 min
const DELAYS = [1000, 5000, 30000, 300000] as const

interface QuizSubmissionPayload {
  attemptId: string
  answers: unknown[]
  quizId: string
}

export interface SyncResult {
  synced: number
  failed: number
}

export async function syncPendingSubmissions(): Promise<SyncResult> {
  const pending = await getPendingSubmissions()
  let synced = 0
  let failed = 0

  for (const item of pending) {
    try {
      if (item.type === 'quiz-submission') {
        const payload = item.payload as QuizSubmissionPayload

        const { error } = await apiFetch('/quiz_attempts')

        if (!error) {
          await markSynced(item.id)
          synced++
        } else {
          failed++
        }
      }
    } catch {
      failed++
    }
  }

  return { synced, failed }
}

export function scheduleSync(attempt: number = 0): void {
  const delay = DELAYS[Math.min(attempt, DELAYS.length - 1)]

  setTimeout(async () => {
    const result = await syncPendingSubmissions()
    if (result.failed > 0 && attempt < DELAYS.length - 1) {
      scheduleSync(attempt + 1)
    }
  }, delay)
}

// EduSync LMS — Feature Flags
// Tenant-aware, rollout-percentage feature flag system backed by API

import { apiFetch } from '@/src/lib/api'

export interface FeatureFlag {
  flag_name: string
  enabled: boolean
  tenant_ids: string[]
  rollout_percentage: number
}

let flagCache: Map<string, FeatureFlag> | null = null
let cacheExpiry = 0
const CACHE_TTL = 5 * 60 * 1000 // 5 minutes

// ---------------------------------------------------------------------------
// Load / refresh cache
// ---------------------------------------------------------------------------

export async function loadFeatureFlags(): Promise<void> {
  if (flagCache && Date.now() < cacheExpiry) return

  const { data } = await apiFetch('/feature_flags')

  flagCache = new Map((data ?? []).map((f: FeatureFlag) => [f.flag_name, f]))
  cacheExpiry = Date.now() + CACHE_TTL
}

export function invalidateFlagCache(): void {
  flagCache = null
  cacheExpiry = 0
}

// ---------------------------------------------------------------------------
// Evaluation helpers
// ---------------------------------------------------------------------------

function hashFlagName(flagName: string): number {
  return flagName.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0)
}

export function isFeatureEnabled(flagName: string, tenantId?: string): boolean {
  if (!flagCache) return false

  const flag = flagCache.get(flagName)
  if (!flag) return false
  if (!flag.enabled) return false

  // Tenant-specific override takes precedence over rollout percentage
  if (tenantId && flag.tenant_ids?.length > 0) {
    return flag.tenant_ids.includes(tenantId)
  }

  // Deterministic rollout by flag name hash
  if (flag.rollout_percentage < 100) {
    return hashFlagName(flagName) % 100 < flag.rollout_percentage
  }

  return true
}

// ---------------------------------------------------------------------------
// React hook (synchronous, uses cached value)
// ---------------------------------------------------------------------------

export function useFeatureFlag(flagName: string): boolean {
  if (!flagCache) return false
  const flag = flagCache.get(flagName)
  return flag?.enabled ?? false
}

// ---------------------------------------------------------------------------
// Admin: persist flag change
// ---------------------------------------------------------------------------

export async function updateFeatureFlag(
  flagName: string,
  updates: Partial<Omit<FeatureFlag, 'flag_name'>>
): Promise<void> {
  await apiFetch('/feature_flags')

  // Invalidate so the next read refreshes from DB
  invalidateFlagCache()
}

// EduSync LMS — Application metrics tracking
// Fire-and-forget: sends metrics to app_metrics table without blocking UI

import { api, apiFetch } from '@/src/lib/api'

export type MetricName =
  | 'quiz.completion_rate'
  | 'quiz.avg_score'
  | 'lesson.avg_time_seconds'
  | 'page.load_time_ms'
  | 'error.rate'
  | 'user.daily_active'
  | 'api.response_time_ms'

/**
 * Track a metric value. Fire-and-forget — never throws.
 */
export async function trackMetric(
  name: MetricName,
  value: number,
  metadata?: Record<string, unknown>
): Promise<void> {
  // Only in production to keep dev DB clean
  if (import.meta.env.DEV) return

  try {
    await apiFetch('/app_metrics')
  } catch {
    // Metrics are non-critical — silently ignore errors
  }
}

/**
 * Measure how long an async operation takes and record it.
 */
export async function measureAsync<T>(
  name: MetricName,
  fn: () => Promise<T>,
  metadata?: Record<string, unknown>
): Promise<T> {
  const start = performance.now()
  const result = await fn()
  const duration = performance.now() - start
  void trackMetric(name, duration, metadata)
  return result
}

export const PERF = {
  LOGIN_START: 'login_start',
  LOGIN_AUTH_COMPLETE: 'login_auth_complete',
  LOGIN_DASHBOARD_RENDERED: 'login_dashboard_rendered',

  COURSE_NAV_START: 'course_nav_start',
  COURSE_DATA_LOADED: 'course_data_loaded',
  COURSE_RENDERED: 'course_rendered',

  QUIZ_START: 'quiz_start',
  QUIZ_DATA_LOADED: 'quiz_data_loaded',
  QUIZ_SUBMIT: 'quiz_submit',
  QUIZ_GRADED: 'quiz_graded',
}

export function perfMark(name: string) {
  if (typeof performance !== 'undefined' && performance.mark) {
    performance.mark(name)
  }
}

export function perfMeasure(name: string, startMark: string, endMark: string): number | null {
  try {
    const entry = performance.measure(name, startMark, endMark)
    if (import.meta.env.DEV) {
      console.log(`⏱ ${name}: ${entry.duration.toFixed(0)}ms`)
    }
    return entry.duration
  } catch {
    return null
  }
}

export function perfMeasureFrom(name: string, startMark: string, endMark: string = 'tti') {
  perfMark(endMark)
  return perfMeasure(name, startMark, endMark)
}

import { useCallback } from 'react'

import { apiFetch } from '@/src/lib/api'

import { useAuth } from '../contexts/AuthContext'

/**
 * useTenantQuery — defense-in-depth helper for tenant-scoped queries.
 *
 * RLS already enforces tenant isolation at the DB level, so these helpers
 * are an additional safety layer. They automatically append
 * `.eq('tenant_id', tenantId)` to queries and include `tenant_id` in inserts.
 *
 * Usage:
 *   const { tenantQuery, tenantInsert } = useTenantQuery();
 *
 *   // SELECT with automatic tenant filter
 *   const { data } = await tenantQuery('classes').select('id, name, created_at');
 *
 *   // INSERT with automatic tenant_id
 *   await tenantInsert('classes', { name: 'English 101', teacher_id: userId });
 */
export function useTenantQuery() {
  const { tenantId } = useAuth()

  /**
   * Returns a API query builder pre-filtered by tenant_id.
   * Caller must chain `.select('col1, col2, ...')` to specify columns.
   * Falls back to an unfiltered query if tenantId is not available
   * (RLS will still enforce isolation).
   */
  const tenantQuery = useCallback(
    (table: string, columns = 'id') => {
      const query = apiFetch('/table')
      if (tenantId) {
        return query.select(columns).eq('tenant_id', tenantId)
      }
      return query.select(columns)
    },
    [tenantId]
  )

  /**
   * Inserts a record with tenant_id automatically added.
   * The auto_set_tenant_id trigger also provides a DB-level fallback.
   */
  const tenantInsert = useCallback(
    async (table: string, data: Record<string, unknown>) => {
      const record = tenantId ? { ...data, tenant_id: tenantId } : data
      return apiFetch('/table')
    },
    [tenantId]
  )

  return { tenantId, tenantQuery, tenantInsert }
}

// EduSync LMS — Core Web Vitals monitoring
// Dev: coloured console badges. Prod: 10 % sample → activity_events table.

import type { Metric } from 'web-vitals'
import { onCLS, onFCP, onINP, onLCP, onTTFB } from 'web-vitals'

import { apiFetch } from '@/src/lib/api'

/* ─── Helpers ──────────────────────────────────────────────── */

const isDev = import.meta.env.DEV

const badgeColors: Record<string, string> = {
  LCP: '#2563eb',
  INP: '#7c3aed',
  CLS: '#dc2626',
  FCP: '#059669',
  TTFB: '#d97706',
}

function ratingEmoji(rating: Metric['rating']): string {
  if (rating === 'good') return '[GOOD]'
  if (rating === 'needs-improvement') return '[NEEDS IMPROVEMENT]'
  return '[POOR]'
}

function logMetricDev(metric: Metric): void {
  const color = badgeColors[metric.name] ?? '#6b7280'

  if (import.meta.env.DEV) {
    console.log(
      `%c ${metric.name} %c ${metric.value.toFixed(1)} ${ratingEmoji(metric.rating)}`,
      `background:${color};color:#fff;padding:2px 6px;border-radius:3px;font-weight:bold`,
      'color:inherit'
    )
  }
}

async function sendMetricProd(metric: Metric): Promise<void> {
  // 10 % sampling
  if (Math.random() > 0.1) return

  try {
    await apiFetch('/activity_events')
  } catch {
    // Silently drop — vitals are non-critical telemetry
  }
}

function handleMetric(metric: Metric): void {
  if (isDev) {
    logMetricDev(metric)
  } else {
    sendMetricProd(metric)
  }
}

/* ─── Public API ───────────────────────────────────────────── */

/**
 * Start collecting Core Web Vitals.
 * Call once at app startup (e.g. main.tsx).
 */
export function reportWebVitals(): void {
  onLCP(handleMetric)
  onFCP(handleMetric)
  onTTFB(handleMetric)
  onCLS(handleMetric)
  onINP(handleMetric)
}
